  async function loadProfiles(){const response=await fetch('/api/perfiles?module=control_administrativo&auto_create=false',{cache:'no-store',headers:{Authorization:`Bearer ${token()}`}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(detail(data));state.profiles=data.perfiles||[];const saved=localStorage.getItem('ge_control_facturacion_perfil');state.profileId=String(state.profiles.find(p=>String(p.id)===saved)?.id||state.profiles[0]?.id||'');$('companySelect').innerHTML=state.profiles.length?state.profiles.map(p=>`<option value="${p.id}">${esc(p.nombre)}${p.rfc?' · '+esc(p.rfc):''}</option>`).join(''):'<option value="">Sin empresas habilitadas</option>';$('companySelect').value=state.profileId;if(!state.profileId)throw new Error('No hay empresas habilitadas para Administrador de empresas.');localStorage.setItem('ge_control_facturacion_perfil',state.profileId)}
  async function loadAll(){if(!state.profileId)return;const results=await Promise.allSettled([api('/configuracion-fiscal'),api('/clientes'),api('/productos'),api('/facturas'),api('/programaciones'),api('/complementos-pago')]);const names=['config','clients','products','invoices','schedules','complements'];results.forEach((result,index)=>{if(result.status==='rejected'){notify(result.reason.message,false);state[names[index]]=index===0?null:[]}else{const data=result.value;if(index===0)state.config=data.configuracion||null;else state[names[index]]=data[responseKeys[names[index]]]||[]}});renderAll()}
  function renderAll(){const profile=state.profiles.find(p=>String(p.id)===state.profileId),now=new Date(),monthRows=state.invoices.filter(i=>{const d=new Date(i.created_at);return d.getFullYear()===now.getFullYear()&&d.getMonth()===now.getMonth()&&i.status==='timbrada'}),paid=monthRows.filter(i=>i.estado_pago==='pagada'),pending=monthRows.filter(i=>i.estado_pago!=='pagada'),sum=rows=>rows.reduce((total,row)=>total+Number(invoiceParty(row).total||0),0);$('companySubtitle').textContent=profile?`${profile.nombre}${profile.rfc?' · '+profile.rfc:''}`:'Sin empresa seleccionada';$('kpiMonthTotal').textContent=money(sum(monthRows));$('kpiInvoices').textContent=`${monthRows.length} factura${monthRows.length===1?'':'s'} del mes`;$('kpiPaidTotal').textContent=money(sum(paid));$('kpiPendingTotal').textContent=money(sum(pending));$('kpiPendingCount').textContent=`${pending.length} pendiente${pending.length===1?'':'s'}`;$('kpiSchedules').textContent=state.schedules.filter(s=>s.status==='activa').length;renderInvoices();renderPortfolio();renderComplements();renderClients();renderProducts();renderSchedules();renderConfig();fillInvoiceClients();renderConcepts()}
  function invoiceParty(row){const c=row?.cfdi_json||{};return {name:c.Receptor?.Nombre||'—',total:c.Total||0}}
  function statusPill(status){const kind=status==='timbrada'||status==='activa'?'ok':status==='rechazada'||status==='cancelada'?'bad':'warn';return `<span class="pill ${kind}">${esc(status||'pendiente')}</span>`}
  function paymentPill(status){return status==='pagada'?'<span class="pill ok">Pagada</span>':'<span class="pill warn">Por cobrar</span>'}
