  function togglePaymentInvoice(id,checked){const row=state.invoices.find(r=>String(r.id)===String(id));if(!row)return;if(checked){const selected=Object.values(state.paymentSelection),rfc=row.cfdi_json?.Receptor?.Rfc;if(selected.length&&selected[0].rfc!==rfc){notify('Selecciona facturas del mismo cliente.',false);renderComplements();return}state.paymentSelection[id]={amount:invoiceBalance(row),rfc,name:invoiceParty(row).name}}else delete state.paymentSelection[id];renderComplements()}
  function updatePaymentSelection(){const rows=Object.values(state.paymentSelection),total=rows.reduce((n,r)=>n+Number(r.amount||0),0);$('paymentSelectedTotal').textContent=money(total);$('paymentSelectedClient').textContent=rows[0]?.name||'Sin cliente seleccionado';$('stampPaymentComplement').disabled=!rows.length||total<=0}
  async function downloadProtected(path,filename){try{const response=await fetch(`/api/general-facturacion${path}`,{headers:authHeaders()});if(!response.ok)throw new Error(detail(await response.json().catch(()=>({}))));const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}catch(error){notify(error.message,false)}}
  function renderClients(){const q=($('clientSearch')?.value||'').toLowerCase();const rows=state.clients.filter(c=>`${c.nombre} ${c.rfc}`.toLowerCase().includes(q));$('clientRows').innerHTML=rows.map(c=>`<tr><td><b>${esc(c.nombre)}</b></td><td>${esc(c.rfc)}</td><td>${esc(c.codigo_postal)}</td><td>${esc(c.regimen_fiscal)}</td><td>${esc(c.uso_cfdi)}</td><td>${[c.retencion_isr?`ISR ${Number(c.retencion_isr_tasa||.0125)*100}%`:'',c.retencion_iva?`IVA ${Number(c.retencion_iva_tasa||.106667)*100}%`:''].filter(Boolean).join(' · ')||'No'}</td><td>${Number(c.dias_credito||0)?`${Number(c.dias_credito)} días`:'Al emitir'}</td><td>${esc(c.email||'—')}</td><td><div class="row-actions"><button class="row-btn" data-edit-client="${c.id}">Editar</button><button class="row-btn" data-delete-client="${c.id}">Eliminar</button></div></td></tr>`).join('')||'<tr><td class="empty" colspan="9">No hay clientes registrados.</td></tr>';document.querySelectorAll('[data-edit-client]').forEach(b=>b.onclick=()=>openClient(b.dataset.editClient));document.querySelectorAll('[data-delete-client]').forEach(b=>b.onclick=()=>deleteClient(b.dataset.deleteClient));fillInvoiceClients()}
