  function actionIcon(icon,label,attrs){const fileLabel=label==='Descargar PDF'?'PDF':label==='Descargar XML'?'XML':'';return `<button class="row-btn ${fileLabel?'file-action':'icon-action'}" type="button" title="${esc(label)}" aria-label="${esc(label)}" ${attrs}>${fileLabel||icon}</button>`}
  function friendlyExecutionError(value){const message=String(value||'No fue posible timbrar esta factura.');if(message.includes('Timbrado diferido por turno'))return 'Está esperando turno para evitar dos timbrados simultáneos. El sistema volverá a intentarlo automáticamente.';const match=message.match(/(CFDI\d+)\s*-?\s*(.*)/);return match?`${match[1]} · ${match[2]}`:message}
  function executionResult(schedule){const run=schedule.ultima_ejecucion;if(!run)return '<div class="execution-result"><span class="pill warn">Sin intentos</span><small>Se intentará en la fecha programada.</small></div>';const successful=run.status==='completada'||run.status==='timbrada',processing=run.status==='procesando';if(successful)return `<div class="execution-result"><span class="pill ok">Timbrada</span><small>${date(run.updated_at||run.created_at)}</small><div class="execution-ok">CFDI generado correctamente</div></div>`;if(processing)return `<div class="execution-result"><span class="pill warn">Procesando</span><small>Enviado al servicio de timbrado.</small></div>`;return `<div class="execution-result"><span class="pill bad">Error al timbrar</span><small>Intento: ${date(run.updated_at||run.created_at)}</small><div class="execution-error">${esc(friendlyExecutionError(run.error))}</div></div>`}
  function renderSchedules(){const row=s=>{const cfdi=s.payload_json||{},ret=Number(cfdi.Impuestos?.TotalImpuestosRetenidos||0),method=cfdi.MetodoPago==='PUE'?'PUE':cfdi.MetodoPago==='PPD'?'PPD':'—',next=s.proxima_ejecucion_at?`<br><small>Próxima: ${date(s.proxima_ejecucion_at)}</small>`:'';return `<tr><td><b>${esc(s.nombre)}</b><br><small>${esc(s.email_destino||'Sin correo')}</small></td><td>Día ${esc(s.dia_mes)} · ${esc(s.hora_local)}<br><small>${esc(s.timezone)}</small>${next}</td><td><b>${esc(cfdi.Receptor?.Nombre||'—')}</b><br><small>RFC ${esc(cfdi.Receptor?.Rfc||'—')}</small></td><td>${money(cfdi.Total)}</td><td><b>${method}</b><br><small>${method==='PUE'?'Una exhibición':method==='PPD'?'Pago diferido':'Sin definir'}</small></td><td>${ret?`Retenciones ${money(ret)}`:'Sin retención'}</td><td>${statusPill(s.status)}</td><td>${executionResult(s)}</td><td><div class="row-actions schedule-actions">${actionIcon('▧','Vista previa PDF sin timbrar',`data-preview-schedule="${s.id}"`)}${actionIcon('✎','Editar programación',`data-edit-schedule="${s.id}"`)}${s.status==='activa'?actionIcon('▶','Reintentar o ejecutar este mes',`data-run-schedule="${s.id}"`):''}${s.status!=='activa'?actionIcon('●','Activar',`data-schedule-state="${s.id}:activa"`):actionIcon('Ⅱ','Pausar',`data-schedule-state="${s.id}:pausada"`)}${actionIcon('×','Cancelar',`data-schedule-state="${s.id}:cancelada"`)}</div></td></tr>`};$('activeScheduleRows').innerHTML=state.schedules.filter(s=>s.status==='activa').map(row).join('')||'<tr><td class="empty" colspan="9">No hay programaciones activas.</td></tr>';$('pausedScheduleRows').innerHTML=state.schedules.filter(s=>s.status==='pausada').map(row).join('')||'<tr><td class="empty" colspan="9">No hay programaciones pausadas.</td></tr>';document.querySelectorAll('[data-preview-schedule]').forEach(b=>b.onclick=()=>previewSchedulePdf(b.dataset.previewSchedule));document.querySelectorAll('[data-edit-schedule]').forEach(b=>b.onclick=()=>openScheduleEditor(b.dataset.editSchedule));document.querySelectorAll('[data-schedule-state]').forEach(b=>b.onclick=()=>{const [id,status]=b.dataset.scheduleState.split(':');changeSchedule(id,status)});document.querySelectorAll('[data-run-schedule]').forEach(b=>b.onclick=()=>runSchedule(b.dataset.runSchedule))}
  function logoOptions(selected='1'){const c=state.config||{},items=[['1',c.logo_1_nombre||'Principal',Boolean(c.logo_1_data_url||c.logo_data_url)],['2',c.logo_2_nombre||'Alternativo',Boolean(c.logo_2_data_url)]];return items.map(([value,name,ready])=>`<option value="${value}" ${String(value)===String(selected)?'selected':''}>${esc(name)}${ready?'':' · sin imagen'}</option>`).join('')}
  function refreshInvoiceLogo(selected){$('invoiceLogo').innerHTML=logoOptions(selected||$('invoiceLogo').value||'1')}
  function ensurePdfColorControls(){if(!$('configExpeditionZip')){const fiscalZip=$('configZip'),label=document.createElement('label');fiscalZip.closest('label').childNodes[0].textContent='Código postal fiscal';label.innerHTML='Lugar de expedición<input id="configExpeditionZip" inputmode="numeric" pattern="\\d{5}" maxlength="5" required><small>Puede ser distinto al domicilio fiscal.</small>';fiscalZip.closest('label').after(label)}if($('configPdfHeader'))return;const panel=document.createElement('div');panel.className='full pdf-colors';panel.innerHTML='<div><h2>Colores del PDF</h2><p>Personaliza la factura impresa para esta empresa.</p></div><label>Encabezados<input id="configPdfHeader" type="color"></label><label>Texto de encabezados<input id="configPdfHeaderText" type="color"></label><label>Títulos<input id="configPdfTitle" type="color"></label>';$('configForm').querySelector('.logos-grid').before(panel)}
  function renderConfig(){ensurePdfColorControls();const c=state.config||{};$('configRfc').value=c.rfc||state.profiles.find(p=>String(p.id)===state.profileId)?.rfc||'';$('configName').value=c.nombre_razon_social||state.profiles.find(p=>String(p.id)===state.profileId)?.nombre||'';$('configZip').value=c.codigo_postal||'';$('configExpeditionZip').value=c.lugar_expedicion||c.codigo_postal||'';$('configRegime').value=c.regimen_fiscal||'';$('configSerie').value=c.serie||'';$('configMethod').value=c.metodo_pago_default||'PPD';$('configPayment').value=c.forma_pago_default||'99';$('configEmail').value=c.email_envio||'';$('configPdfHeader').value=c.pdf_header_color||'#7A1E2C';$('configPdfHeaderText').value=c.pdf_header_text_color||'#FFFFFF';$('configPdfTitle').value=c.pdf_title_color||'#4E111C';$('configLogo1Name').value=c.logo_1_nombre||'Principal';$('configLogo2Name').value=c.logo_2_nombre||'Alternativo';setConfigLogo(1,c.logo_1_data_url||c.logo_data_url||'');setConfigLogo(2,c.logo_2_data_url||'');refreshInvoiceLogo()}
  function setConfigLogo(slot,value){$(`configLogo${slot}Data`).value=value||'';$(`configLogo${slot}Preview`).src=value||'';$(`configLogo${slot}Preview`).hidden=!value;$(`configLogo${slot}Empty`).hidden=Boolean(value)}
  function loadConfigLogo(slot,event){const file=event.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){notify('El logo debe ser PNG, JPG o WebP.',false);event.target.value='';return}if(file.size>350000){notify('El logo debe pesar menos de 350 KB.',false);event.target.value='';return}const reader=new FileReader();reader.onload=()=>setConfigLogo(slot,String(reader.result||''));reader.readAsDataURL(file)}
  function fillInvoiceClients(){const current=$('invoiceClient').value;$('invoiceClient').innerHTML='<option value="">Selecciona un cliente</option>'+state.clients.map(c=>`<option value="${c.id}">${esc(c.nombre)} · ${esc(c.rfc)}</option>`).join('');if(state.clients.some(c=>String(c.id)===current))$('invoiceClient').value=current;showReceiver()}
  function prepareInvoice(){if(!$('invoiceSerie').value)$('invoiceSerie').value=state.config?.serie||'';$('invoiceMethod').value=state.config?.metodo_pago_default||'PPD';$('invoicePayment').value=state.config?.forma_pago_default||'99';refreshInvoiceLogo();if(!state.concepts.length)addConcept();if(!state.config)setValidation('Antes de facturar, completa la Configuración fiscal del emisor.',false)}
  function addConcept(productId=''){state.concepts.push({key:crypto.randomUUID(),productId:String(productId),quantity:1,price:'',iva:'',object:'02',includeIva:false});invalidate();renderConcepts()}
  function renderConcepts(){const options='<option value="">Selecciona producto o servicio</option>'+state.products.map(p=>`<option value="${p.id}">${esc(p.descripcion)} · ${esc(p.clave_prod_serv)}</option>`).join('');$('conceptRows').innerHTML=state.concepts.map((c,index)=>`<div class="concept-row" data-concept="${c.key}"><label>Producto o servicio<select data-field="product">${options}</select><span class="concept-desc" data-description></span></label><label>Cantidad<input data-field="quantity" type="number" min="0.000001" step="0.000001" value="${esc(c.quantity)}"></label><label>Precio unitario<input data-field="price" type="number" min="0" step="0.01" value="${esc(c.price)}"></label><label>IVA<select data-field="iva"><option value="0">0%</option><option value="0.08">8%</option><option value="0.16">16%</option></select></label><button class="icon-btn" data-remove="${index}" type="button" aria-label="Eliminar">×</button></div>`).join('');document.querySelectorAll('[data-concept]').forEach((row,index)=>{const c=state.concepts[index],product=state.products.find(p=>String(p.id)===c.productId);row.querySelector('[data-field="product"]').value=c.productId;row.querySelector('[data-field="iva"]').value=String(c.iva||product?.iva_tasa||0);row.querySelector('[data-description]').textContent=product?`${product.clave_prod_serv} · ${product.clave_unidad}${product.unidad?' · '+product.unidad:''} · ${product.precio_incluye_iva?'precio final con IVA':'precio antes de IVA'}`:'';row.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>updateConcept(index,input.dataset.field,input.value));row.querySelector('[data-remove]').onclick=()=>{state.concepts.splice(index,1);if(!state.concepts.length)addConcept();else{invalidate();renderConcepts()}}});calculateTotals()}
  function updateConcept(index,field,value){const c=state.concepts[index];if(field==='product'){c.productId=value;const p=state.products.find(row=>String(row.id)===value);if(p){c.price=String(p.valor_unitario??'');c.iva=String(p.iva_tasa??0);c.object=p.objeto_imp||'02';c.includeIva=Boolean(p.precio_incluye_iva)}renderConcepts()}else{c[field]=value;invalidate();calculateTotals()}}
  function calculateTotals(){let subtotal=0,tax=0;state.concepts.forEach(c=>{const gross=Number(c.quantity||0)*Number(c.price||0),rate=Number(c.iva||0),base=c.includeIva&&rate?gross/(1+rate):gross;subtotal+=base;tax+=base*rate});const client=state.clients.find(row=>String(row.id)===$('invoiceClient').value),isr=$('invoiceIsr').checked?subtotal*Number(client?.retencion_isr_tasa||.0125):0,ivaRetention=$('invoiceIvaRetention').checked?subtotal*Number(client?.retencion_iva_tasa||.106667):0;$('subtotal').textContent=money(subtotal);$('taxTotal').textContent=money(tax);$('isrTotalRow').hidden=!isr;$('isrTotal').textContent=`-${money(isr)}`;$('ivaRetentionTotalRow').hidden=!ivaRetention;$('ivaRetentionTotal').textContent=`-${money(ivaRetention)}`;$('grandTotal').textContent=money(subtotal+tax-isr-ivaRetention);$('previewReceiver').textContent=client?`${client.nombre} · ${client.rfc}`:'Sin seleccionar';$('previewPayment').textContent=`${$('invoiceMethod').value} · ${$('invoicePayment').selectedOptions[0]?.textContent||'Por definir'}`;$('previewConcepts').textContent=`${state.concepts.filter(c=>c.productId).length} producto(s) o servicio(s)`}
  function showReceiver(){const c=state.clients.find(row=>String(row.id)===$('invoiceClient').value),isPublic=c?.rfc==='XAXX010101000';$('invoiceIsr').checked=Boolean(c?.retencion_isr);$('invoiceIsr').disabled=!c?.retencion_isr;$('invoiceIvaRetention').checked=Boolean(c?.retencion_iva);$('invoiceIvaRetention').disabled=!c?.retencion_iva;$('invoiceGlobal').checked=Boolean(isPublic);$('receiverSummary').innerHTML=c?`<b>${esc(c.nombre)}</b><br>RFC ${esc(c.rfc)} · CP ${esc(c.codigo_postal)} · Régimen ${esc(c.regimen_fiscal)} · Uso CFDI ${esc(c.uso_cfdi)}${c.retencion_isr?`<br>Retención ISR: ${Number(c.retencion_isr_tasa||.0125)*100}%`:'<br>Sin retención de ISR'}${c.retencion_iva?`<br>Retención IVA: ${Number(c.retencion_iva_tasa||.106667)*100}%`:'<br>Sin retención de IVA'}${isPublic?'<br>El sistema preparará automáticamente la información global del mes.':''}<br>Correo de envío: <b>${esc(c.email||'Sin correo registrado')}</b>`:'Selecciona un cliente del catálogo.';invalidate();calculateTotals()}
  function invalidate(){state.validated=null;$('stampInvoice').disabled=true;$('validationResult').hidden=true;calculateTotals()}
  function buildPayload(){const cfg=state.config;if(!cfg)throw new Error('Completa primero la configuración fiscal.');const client=state.clients.find(c=>String(c.id)===$('invoiceClient').value);if(!client)throw new Error('Selecciona un cliente.');const isGlobal=client.rfc==='XAXX010101000';const concepts=state.concepts.map(c=>{const p=state.products.find(row=>String(row.id)===c.productId);if(!p)throw new Error('Selecciona el producto o servicio de todos los conceptos.');return {clave_prod_serv:p.clave_prod_serv,cantidad:Number(c.quantity),clave_unidad:p.clave_unidad,unidad:p.unidad||'',descripcion:p.descripcion,no_identificacion:p.no_identificacion||null,valor_unitario:Number(c.price),objeto_imp:p.objeto_imp||'02',iva_tasa:Number(c.iva||0),iva_incluido:Boolean(p.precio_incluye_iva)}});const period=($('globalMonth').value||new Date().toISOString().slice(0,7)).split('-');return {emisor:{rfc:cfg.rfc,nombre:cfg.nombre_razon_social,codigo_postal:cfg.codigo_postal,regimen_fiscal:cfg.regimen_fiscal},receptor:{rfc:client.rfc,nombre:client.nombre,codigo_postal:client.codigo_postal,regimen_fiscal:client.regimen_fiscal,uso_cfdi:client.uso_cfdi},conceptos:concepts,tipo_comprobante:'I',moneda:'MXN',tipo_cambio:null,forma_pago:$('invoicePayment').value,metodo_pago:$('invoiceMethod').value,lugar_expedicion:cfg.lugar_expedicion||cfg.codigo_postal,exportacion:'01',serie:$('invoiceSerie').value.trim()||null,folio:null,retencion_isr_tasa:$('invoiceIsr').checked?Number(client.retencion_isr_tasa||.0125):0,retencion_iva_tasa:$('invoiceIvaRetention').checked?Number(client.retencion_iva_tasa||.106667):0,informacion_global_periodicidad:isGlobal?'04':null,informacion_global_meses:isGlobal?period[1]:null,informacion_global_anio:isGlobal?Number(period[0]):null,notas:$('invoiceNotes').value.trim()||null}}
  async function validateInvoice(){try{const payload=buildPayload();const data=await api('/validar',{method:'POST',body:JSON.stringify(payload)});state.validated={payload,cfdi:data.cfdi};$('stampInvoice').disabled=false;setValidation(`Factura válida. Total ${money(data.cfdi.Total)}. Ya puedes enviarla a timbrar.`,true)}catch(error){invalidate();setValidation(error.message,false)}}
